<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Policy\Allow\Create;

use Override;
use Throwable;

use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Create\TemplateVersionCreateAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedCreateAllow
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(private readonly Context $context)
  {
  }
  public function __invoke(TemplateVersionCreateAllowDecision $proposal): TemplateVersionCreateAllowDecision
  {
    $this->logDebug("Check IsAuthenticatedCreateAllow Template version");
    $span = $this->startSpan("Check IsAuthenticatedCreateAllow Template version");
    try {
      $userContext = $this->context->getIdentity();
      if( $proposal->isAllowed()) {
        if( ! !$userContext->anonymous ) {
          $proposal->deny('Disabled if not IsAuthenticatedCreate');
        }      }
      return $proposal;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
